strings:
:root {
  --background: white;
  --border: #dcdcde;
  --color: #3a383f;
  --subtle: #626168;
  --link: #0b5cad;

  background-color: var(--background);
  color: var(--color);
}

body {
  text-align: center;
  font-family: "GitLab Sans", -apple-system, BlinkMacSystemFont,
    "Segoe UI", Roboto, "Noto Sans", Ubuntu, Cantarell, "Helvetica Neue",
    sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
    "Noto Color Emoji";
  margin: auto;
  font-size: 14px;
}

h1 {
  font-size: 56px;
  line-height: 100px;
  font-weight: 400;
  color: var(--subtle);
}

h2 {
  color: var(--subtle);
  font-size: 20px;
  font-weight: 400;
  line-height: 28px;
}

hr {
  max-width: 800px;
  margin: 18px auto;
  border: 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--background);
}

img {
  max-width: 40vw;
  display: block;
  margin: 40px auto;
}

a {
  line-height: 100px;
  font-weight: 400;
  color: var(--link);
  font-size: 18px;
  text-decoration: none;
}

.container {
  margin: auto 20px;
}

.go-back {
  display: none;
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #18171d;
    --border: #4c4b51;
    --color: #ececef;
    --subtle: #bfbfc3;
    --link: #9dc7f1;
  }
}
